-- Who is who: the first call from a phone claims its id; after that only that phone's secret works.
create table if not exists public.score_players (
  id text primary key,
  secret_hash text not null,
  name text,
  handle text,
  house text,
  created_at timestamptz not null default now(),
  seen_at timestamptz not null default now()
);
alter table public.score_players enable row level security;

create table if not exists public.activity_log (
  id bigint generated always as identity primary key,
  event text unique,
  player text not null,
  activity text not null,
  place text,
  category text,
  client_at timestamptz,
  at timestamptz not null default now(),
  day date not null,
  week date not null,
  board text,
  points int not null default 0
);
create index if not exists activity_log_player_day_idx on public.activity_log (player, day, activity);
create index if not exists activity_log_board_idx on public.activity_log (week, board, player) where points > 0;
alter table public.activity_log enable row level security;
drop policy if exists "admins read the activity log" on public.activity_log;
create policy "admins read the activity log" on public.activity_log for select using (public.is_admin());

create table if not exists public.score_badges (
  week date not null,
  board text not null,
  rank int not null check (rank between 1 and 3),
  player text not null,
  points int not null,
  primary key (week, board, rank)
);
alter table public.score_badges enable row level security;
create table if not exists public.score_weeks_closed (week date primary key, closed_at timestamptz not null default now());
alter table public.score_weeks_closed enable row level security;

-- The SAST day, and the Monday of the SAST week, of "now".
create or replace function public.sast_day() returns date language sql stable as $$ select (now() at time zone 'Africa/Johannesburg')::date $$;
create or replace function public.sast_week() returns date language sql stable as $$ select date_trunc('week', now() at time zone 'Africa/Johannesburg')::date $$;

-- Weeks that have finished (and are not before the first badge week) give their top 3 on each board a badge.
create or replace function public.close_finished_weeks() returns void language plpgsql security definer set search_path = public as $$
declare w date; first_week date; b text;
begin
  select value::date into first_week from score_config where key = 'first_badge_week';
  for w in
    select distinct week from activity_log
    where week < sast_week() and week >= coalesce(first_week, '2100-01-01') and points > 0
      and week not in (select week from score_weeks_closed)
  loop
    foreach b in array array['academics', 'social', 'sport'] loop
      insert into score_badges (week, board, rank, player, points)
      select w, b, t.rank, t.player, t.pts from (
        select player, sum(points)::int as pts, row_number() over (order by sum(points) desc, max(at) asc)::int as rank
        from activity_log where week = w and board = b and points > 0 group by player
      ) t where t.rank <= 3
      on conflict do nothing;
    end loop;
    insert into score_weeks_closed (week) values (w) on conflict do nothing;
  end loop;
end $$;

-- Log (and score) one finished activity. Returns { ok, scored, points, board, used, limit, reason }.
create or replace function public.record_activity(
  p_id text, p_secret text, p_event text, p_activity text, p_place text, p_category text, p_client_at timestamptz,
  p_name text default null, p_handle text default null, p_house text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  rule score_rules%rowtype;
  d date := sast_day();
  w date := sast_week();
  used int := 0;
  pts int := 0;
  brd text := null;
  nm text := left(coalesce(p_name, ''), 24);
  today int;
begin
  if p_id is null or length(p_id) not between 8 and 64 or p_secret is null or length(p_secret) < 16
     or p_event is null or length(p_event) not between 6 and 40
     or p_activity is null or p_activity !~ '^[a-z0-9_]{1,40}$' then
    raise exception 'bad activity';
  end if;
  perform pg_advisory_xact_lock(hashtext(p_id));
  -- the name on the board is cleaned like chat (a slur: the name becomes Student)
  begin
    nm := public.clean_chat_body(nm);
  exception when others then
    nm := 'Student';
  end;
  insert into score_players (id, secret_hash, name, handle, house)
  values (p_id, md5(p_secret), nm, left(coalesce(p_handle, ''), 20), left(coalesce(p_house, ''), 40))
  on conflict (id) do nothing;
  if (select secret_hash from score_players where id = p_id) <> md5(p_secret) then raise exception 'not you'; end if;
  update score_players set name = nm, handle = left(coalesce(p_handle, ''), 20), house = left(coalesce(p_house, ''), 40), seen_at = now() where id = p_id;
  if exists (select 1 from activity_log where event = p_event) then return jsonb_build_object('ok', true, 'dup', true); end if;
  select count(*) into today from activity_log where player = p_id and day = d;
  if today >= 600 then return jsonb_build_object('ok', false, 'reason', 'too_many'); end if;
  select * into rule from score_rules where activity_id = p_activity;
  if found then
    select count(*) into used from activity_log where player = p_id and day = d and activity = p_activity and points > 0;
    if used < rule.daily_limit then pts := rule.points; brd := rule.board; used := used + 1; end if;
  end if;
  insert into activity_log (event, player, activity, place, category, client_at, day, week, board, points)
  values (p_event, p_id, p_activity, left(p_place, 40), left(p_category, 20), p_client_at, d, w, brd, pts);
  perform close_finished_weeks();
  return jsonb_build_object('ok', true, 'scored', pts > 0, 'points', pts, 'board', rule.board,
    'used', used, 'limit', rule.daily_limit,
    'reason', case when rule.activity_id is null then 'no_score' when pts = 0 then 'daily_limit' else 'ok' end);
end $$;
grant execute on function public.record_activity(text, text, text, text, text, text, timestamptz, text, text, text) to anon, authenticated;

-- This week's top 10 on a board, and where p_id stands.
create or replace function public.score_board(p_board text, p_id text default null)
returns jsonb language plpgsql security definer set search_path = public as $$
declare w date := sast_week(); top jsonb; you jsonb;
begin
  if p_board not in ('academics', 'social', 'sport') then raise exception 'unknown board'; end if;
  perform close_finished_weeks();
  with ranked as (
    select player, sum(points)::int as pts, (row_number() over (order by sum(points) desc, max(at) asc))::int as rank
    from activity_log where week = w and board = p_board and points > 0 group by player
  )
  select
    coalesce((select jsonb_agg(jsonb_build_object('rank', r.rank, 'name', coalesce(nullif(p.name, ''), 'Student'), 'handle', coalesce(p.handle, ''),
        'house', coalesce(p.house, ''), 'points', r.pts, 'you', r.player = p_id) order by r.rank)
      from ranked r left join score_players p on p.id = r.player where r.rank <= 10), '[]'::jsonb),
    (select jsonb_build_object('rank', r.rank, 'points', r.pts) from ranked r where r.player = p_id)
  into top, you;
  return jsonb_build_object('week', w, 'top', top, 'you', you);
end $$;
grant execute on function public.score_board(text, text) to anon, authenticated;

-- The badges a player won in weeks gone by.
create or replace function public.my_badges(p_id text)
returns jsonb language sql stable security definer set search_path = public as $$
  select coalesce(jsonb_agg(jsonb_build_object('week', week, 'board', board, 'rank', rank) order by week, board), '[]'::jsonb)
  from score_badges where player = p_id
$$;
grant execute on function public.my_badges(text) to anon, authenticated;

-- Errors and funnel events (src/errors.js, src/events.js): who sent it, and a limit per player per hour.
alter table public.client_errors add column if not exists player text;
create index if not exists client_errors_player_idx on public.client_errors (player, created_at desc);
-- (security definer: the player who sends cannot read the table, but the count must see every row)
create or replace function public.client_errors_limit() returns trigger language plpgsql security definer set search_path = public as $$
declare is_funnel boolean := coalesce(new.kind, '') = 'funnel'; cap int; sent int;
begin
  if new.player is not null then
    cap := case when is_funnel then 40 else 20 end;
    select count(*) into sent from public.client_errors
      where player = new.player and (kind = 'funnel') = is_funnel and created_at > now() - interval '1 hour';
    if sent >= cap then
      return null; -- over the limit: the row is quietly dropped
    end if;
  end if;
  return new;
end $$;
drop trigger if exists client_errors_limit_trg on public.client_errors;
create trigger client_errors_limit_trg before insert on public.client_errors for each row execute function public.client_errors_limit();

-- Feedback: the menu button and the third-session pop-up.
create table if not exists public.feedback (
  id bigint generated always as identity primary key,
  created_at timestamptz not null default now(),
  player text,
  stars int check (stars is null or stars between 1 and 5),
  message text check (char_length(message) <= 600),
  kind text check (char_length(kind) <= 20),
  build text check (char_length(build) <= 60),
  device text check (char_length(device) <= 200)
);
alter table public.feedback enable row level security;
grant insert on public.feedback to anon, authenticated;
drop policy if exists "anyone can send feedback" on public.feedback;
create policy "anyone can send feedback" on public.feedback for insert to anon, authenticated with check (true);
drop policy if exists "admins read feedback" on public.feedback;
create policy "admins read feedback" on public.feedback for select using (public.is_admin());

-- CAPACITY (job F, 13 Nov): never break when full. A phone asks to come in (cap_enter) when the game opens and every
-- minute while it plays. Up to max_players are in at once; past that, new arrivals wait in line (oldest first) and
-- come in as space frees; players already in keep playing. A player not seen for stale_seconds frees their place.
-- The owner changes max_players with: update public.cap_config set value = 5000 where key = 'max_players';
create table if not exists public.cap_config (key text primary key, value int not null);
insert into public.cap_config (key, value) values ('max_players', 200), ('stale_seconds', 150) on conflict (key) do nothing; -- (200: a safe start for Supabase Pro with rooms of 20; docs/sprints/capacity/report.md)
alter table public.cap_config enable row level security;
create table if not exists public.cap_sessions (
  player text primary key,
  joined_at timestamptz not null default now(),
  seen_at timestamptz not null default now(),
  admitted boolean not null default false
);
create index if not exists cap_sessions_seen on public.cap_sessions (seen_at);
create index if not exists cap_sessions_wait on public.cap_sessions (admitted, joined_at);
alter table public.cap_sessions enable row level security;

-- OWNER REPORTS (job G, 13 Nov): the same call, once a minute while a phone plays, also notes what the owner's reports
-- need, in one go and never more often: the SAST day this player was here (with their country), how long this
-- session has lasted, which area they were in this minute (by hour), their money now, and how many times the word
-- filter stopped them since the last call. Counts only: nobody's path, no positions, no message text.
create table if not exists public.play_days (player text not null, day date not null, country text, primary key (player, day));
create index if not exists play_days_day on public.play_days (day);
alter table public.play_days enable row level security;
create table if not exists public.play_sessions (id bigint generated always as identity primary key, player text not null, day date not null, started timestamptz not null default now(), last timestamptz not null default now());
create index if not exists play_sessions_player on public.play_sessions (player, last desc);
create index if not exists play_sessions_day on public.play_sessions (day);
alter table public.play_sessions enable row level security;
create table if not exists public.area_minutes (day date not null, hour int not null, area text not null, minutes int not null default 0, primary key (day, hour, area));
alter table public.area_minutes enable row level security;
create table if not exists public.daily_counts (day date not null, kind text not null, n int not null default 0, primary key (day, kind));
alter table public.daily_counts enable row level security;
create table if not exists public.player_money (player text primary key, money int not null, at timestamptz not null default now());
alter table public.player_money enable row level security;

drop function if exists public.cap_enter(text, text);
create or replace function public.cap_enter(p_id text, p_secret text, p_country text default null, p_area text default null, p_money int default null, p_filter int default 0)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  mx int := coalesce((select value from cap_config where key = 'max_players'), 200);
  stale int := coalesce((select value from cap_config where key = 'stale_seconds'), 150);
  inside int;
  me cap_sessions%rowtype;
  before timestamptz;
  pos int;
  d date := (now() at time zone 'Africa/Johannesburg')::date;
  sid bigint;
begin
  if p_id is null or length(p_id) not between 8 and 64 or p_secret is null or length(p_secret) < 16 then raise exception 'bad id'; end if;
  insert into score_players (id, secret_hash) values (p_id, md5(p_secret)) on conflict (id) do nothing;
  if (select secret_hash from score_players where id = p_id) <> md5(p_secret) then raise exception 'not you'; end if;
  perform pg_advisory_xact_lock(hashtext('cap_enter'));
  delete from cap_sessions where seen_at < now() - make_interval(secs => stale);
  select seen_at into before from cap_sessions where player = p_id;
  insert into cap_sessions (player) values (p_id) on conflict (player) do update set seen_at = now();
  select * into me from cap_sessions where player = p_id;
  select count(*) into inside from cap_sessions where admitted;
  if not me.admitted then
    select count(*) + 1 into pos from cap_sessions where not admitted and (joined_at, player) < (me.joined_at, me.player);
    if inside < mx and pos = 1 then
      update cap_sessions set admitted = true where player = p_id;
      me.admitted := true;
      inside := inside + 1;
    else
      return jsonb_build_object('ok', true, 'admitted', false, 'position', pos, 'online', inside, 'max', mx);
    end if;
  end if;
  -- (in and playing: the owner's counts)
  insert into play_days (player, day, country) values (p_id, d, left(nullif(p_country, ''), 60))
    on conflict (player, day) do update set country = coalesce(excluded.country, play_days.country);
  select id into sid from play_sessions where player = p_id and last > now() - interval '3 minutes' order by last desc limit 1;
  if sid is null then insert into play_sessions (player, day) values (p_id, d); else update play_sessions set last = now() where id = sid; end if;
  if p_area is not null and (before is null or before <= now() - interval '50 seconds') then
    insert into area_minutes (day, hour, area, minutes) values (d, extract(hour from now() at time zone 'Africa/Johannesburg')::int, left(p_area, 40), 1)
      on conflict (day, hour, area) do update set minutes = area_minutes.minutes + 1;
  end if;
  if p_money is not null then insert into player_money (player, money, at) values (p_id, p_money, now()) on conflict (player) do update set money = excluded.money, at = now(); end if;
  if coalesce(p_filter, 0) > 0 then
    insert into daily_counts (day, kind, n) values (d, 'filter', least(p_filter, 50)) on conflict (day, kind) do update set n = daily_counts.n + excluded.n;
  end if;
  return jsonb_build_object('ok', true, 'admitted', true, 'online', inside, 'max', mx);
end $$;
grant execute on function public.cap_enter(text, text, text, text, int, int) to anon, authenticated;
-- Leaving (the tab closes): the place frees at once.
create or replace function public.cap_leave(p_id text, p_secret text)
returns void language plpgsql security definer set search_path = public as $$
begin
  if (select secret_hash from score_players where id = p_id) = md5(p_secret) then delete from cap_sessions where player = p_id; end if;
end $$;
grant execute on function public.cap_leave(text, text) to anon, authenticated;
-- #/health: how full the game is (counts only).
create or replace function public.cap_status()
returns jsonb language sql security definer set search_path = public as $$
  select jsonb_build_object('online', (select count(*) from cap_sessions where admitted and seen_at > now() - make_interval(secs => coalesce((select value from cap_config where key = 'stale_seconds'), 150))),
    'waiting', (select count(*) from cap_sessions where not admitted and seen_at > now() - interval '60 seconds'),
    'max', coalesce((select value from cap_config where key = 'max_players'), 200))
$$;
grant execute on function public.cap_status() to anon, authenticated;
-- CAPACITY END
